import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";var i=JSON.parse(`{"title":"版本","description":"","frontmatter":{},"headers":[],"relativePath":"middleware/kubernetes/basic/version.md","filePath":"middleware/kubernetes/basic/version.md"}`),a={name:`middleware/kubernetes/basic/version.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="版本" tabindex="-1">版本 <a class="header-anchor" href="#版本" aria-label="Permalink to “版本”">​</a></h1><ul><li>kubernetes 有3个版本，分别是：minikube、k3s、k8s</li></ul><h2 id="minikube" tabindex="-1">minikube <a class="header-anchor" href="#minikube" aria-label="Permalink to “minikube”">​</a></h2><ul><li>适合本地开发环境，资源占用较大，不适合生产环境</li></ul><h2 id="k3s-精简版k8s" tabindex="-1">k3s [精简版k8s] <a class="header-anchor" href="#k3s-精简版k8s" aria-label="Permalink to “k3s [精简版k8s]”">​</a></h2><ul><li>简单来说：项目小于10节点，选k3s。</li><li>单节点 1 分钟部署完集群，3 节点 HA 半小时搞定；生产 3Master + 多 Worker 架构成熟稳定。</li><li>内置全套中间件，不用自己配网络、存储、ingress，中小团队 1 人可维护十几节点集群。</li><li>3Server 嵌入式 etcd 做高可用，也能对接外置 MySQL，成本远低于原生 K8s 的 etcd 集群。</li></ul><h2 id="k8s" tabindex="-1">k8s <a class="header-anchor" href="#k8s" aria-label="Permalink to “k8s”">​</a></h2><ul><li>简单来说：项目大于10节点，选k8s。</li><li>单集群数千节点、上万 Pod 场景官方最优方案，etcd 集群调优方案成熟。</li><li>所有小众 CRD、云厂商插件、企业级安全组件原生适配无改造。</li><li>etcd 备份、故障修复、多组件分步升级，需要专职 K8s 运维人员。</li></ul>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};